// 24-S6 acceptance: the library as a collaborator, against PostgreSQL (a
// throwaway schema). The session gate is the real one; only Better Auth's
// session read is stubbed. A shared puzzle is listed for its collaborator in
// every state, under its owner's username, with the fields the library
// already had; `listSharedPuzzleIds` names the puzzles the session's account
// collaborates on. Do not edit this file to match an implementation.
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import type { Prisma } from '@prisma/client';
import { createGrid, withLetter } from '@/engine/grid';
import { serializeGrid } from '@/lib/puzzle-storage';
import { createTestDatabase, type TestDatabase } from '@/test-support/database';

const holder = vi.hoisted(() => ({ client: undefined as unknown, session: null as unknown }));
vi.mock('@/lib/prisma', () => ({
  prisma: new Proxy({}, {
    get(_target, key) {
      const client = holder.client as Record<PropertyKey, unknown>;
      const value = Reflect.get(client, key);
      return typeof value === 'function' ? value.bind(client) : value;
    },
  }),
}));
vi.mock('@/lib/auth', () => ({ auth: { api: { getSession: async () => holder.session } } }));
vi.mock('next/headers', () => ({ headers: async () => new Headers() }));
vi.mock('next/cache', () => ({ revalidatePath: () => undefined }));

import * as actions from './actions';

/** Loaded by name, so this file type-checks before the action exists. */
function listSharedPuzzleIds(): Promise<string[]> {
  const action = (actions as Record<string, unknown>).listSharedPuzzleIds;
  expect(typeof action, 'listSharedPuzzleIds').toBe('function');
  return (action as () => Promise<string[]>)();
}

const USERS = {
  adam: { id: 'adam', email: 'adam@library6.example.test', displayName: 'Adam' },
  jay: { id: 'jay', email: 'jay@library6.example.test', displayName: 'Jay' },
  eve: { id: 'eve', email: 'eve@library6.example.test', displayName: 'Eve' },
};
type Name = keyof typeof USERS;
const as = (name: Name) => {
  holder.session = { user: USERS[name], session: {} };
};

let db: TestDatabase;
beforeAll(async () => {
  db = await createTestDatabase();
  holder.client = db.client;
  await db.client.user.createMany({ data: Object.values(USERS).map((user) => ({ ...user, name: user.displayName })) });
}, 60_000);
afterAll(async () => { await db?.drop(); });
beforeEach(() => as('jay'));

const FIELDS = [
  'black', 'builderId', 'builderName', 'cols', 'hintsComplete', 'id', 'phase', 'play',
  'publishedAt', 'rows', 'title', 'updatedAt', 'visibility',
];
const grid = serializeGrid(withLetter(createGrid({ cols: 3, rows: 3 }), { col: 0, row: 0 }, 'Q'));
let serial = 0;
async function seed(builder: Name, options: {
  shareWith?: Name[]; phase?: 'grid' | 'hints'; publishedAt?: Date; visibility?: 'private' | 'public';
} = {}) {
  const title = `S6 ${builder} ${++serial}`;
  const id = (await db.client.puzzle.create({
    data: {
      builderId: builder, title, grid: grid as unknown as Prisma.InputJsonValue, hints: {},
      phase: options.phase ?? 'grid', publishedAt: options.publishedAt ?? null,
      visibility: options.visibility ?? 'private',
    },
  })).id;
  for (const name of options.shareWith ?? []) await db.client.puzzleCollaborator.create({ data: { puzzleId: id, userId: name } });
  return id;
}

describe('24-S6-2 the library as a collaborator', () => {
  it('lists the shared puzzles in Build, Create Hints and published unlisted, under the owner’s username, with the same fields', async () => {
    const build = await seed('adam', { shareWith: ['jay'] });
    const hints = await seed('adam', { shareWith: ['jay'], phase: 'hints' });
    const unlisted = await seed('adam', { shareWith: ['jay'], phase: 'hints', publishedAt: new Date('2026-11-01T00:00:00Z') });
    const notShared = await seed('adam');
    const othersShared = await seed('adam', { shareWith: ['eve'] });

    const rows = await actions.listPuzzles();
    const ids = rows.map((row) => row.id);
    expect(ids).toEqual(expect.arrayContaining([build, hints, unlisted]));
    expect(ids).not.toContain(notShared);
    expect(ids).not.toContain(othersShared);
    for (const id of [build, hints, unlisted]) {
      const row = rows.find((candidate) => candidate.id === id)!;
      expect(row.builderId).toBe('adam');
      expect(row.builderName).toBe('Adam');
      expect(Object.keys(row).sort()).toEqual(FIELDS);
    }
    expect(rows.find((row) => row.id === hints)!.phase).toBe('hints');
    expect(rows.find((row) => row.id === unlisted)!.visibility).toBe('private');
  });

  it('no longer lists a puzzle once the collaborator is removed', async () => {
    const id = await seed('adam', { shareWith: ['jay'] });
    expect((await actions.listPuzzles()).map((row) => row.id)).toContain(id);
    await db.client.puzzleCollaborator.delete({ where: { puzzleId_userId: { puzzleId: id, userId: 'jay' } } });
    expect((await actions.listPuzzles()).map((row) => row.id)).not.toContain(id);
  });

  it('listSharedPuzzleIds names exactly the puzzles the account collaborates on', async () => {
    const shared = await seed('adam', { shareWith: ['jay'] });
    const sharedToo = await seed('eve', { shareWith: ['jay', 'adam'] });
    const own = await seed('jay', { shareWith: ['adam'] });
    const others = await seed('adam', { shareWith: ['eve'] });

    const jays = await listSharedPuzzleIds();
    expect(jays).toEqual(expect.arrayContaining([shared, sharedToo]));
    expect(jays).not.toContain(own);
    expect(jays).not.toContain(others);

    as('adam');
    const adams = await listSharedPuzzleIds();
    expect(adams).toEqual(expect.arrayContaining([sharedToo, own]));
    expect(adams).not.toContain(shared);
    expect(adams).not.toContain(others);
  });
});
